1	var LOG = TemuLogger.createLogger('popup');
2	
3	function send(type, extra) {
4	  return new Promise((res) => chrome.runtime.sendMessage(Object.assign({ type }, extra), res));
5	}
6	function esc(s) {
7	  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
8	}
9	function setMsg(text, cls) {
10	  const el = document.getElementById('msg');
11	  el.textContent = text || '';
12	  el.className = cls || '';
13	}
14	function fmtTs(ts) {
15	  return ts ? new Date(ts).toLocaleString('zh-CN') : '—';
16	}
17	function num(v) { return v != null ? v : '—'; }
18	function editLink(productId) { return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId; }
19	function itemsHtml(items, label, color) {
20	  if (!Array.isArray(items) || !items.length) return '';
21	  return `<div class="items">${esc(label)}${items.map((it) =>
22	    `<a href="${esc(editLink(it.productId))}" target="_blank" style="color:${color}" title="SKC ${esc(it.skc || '-')}">• ${esc((it.name || '商品').slice(0, 22))}</a>`
23	  ).join('')}</div>`;
24	}
25	function skuSpecsHtml(specs) {
26	  if (!Array.isArray(specs) || !specs.length) return '';
27	  const names = specs.map((s) => esc((s.name || 'SKU').slice(0, 20))).join('、');
28	  return `<div class="items" style="color:#1f2329">SKU规格（${specs.length}个）：${names}</div>`;
29	}
30	function frontProductHtml(storeName, frontData, productUrls) {
31	  // frontData: { [url]: { title, price, variants, totalOptions, availableOptions, ts } }
32	  // productUrls: { [store]: [url1, url2, ...] }
33	  const urls = (productUrls && productUrls[storeName]) || [];
34	  const entries = Object.entries(frontData || {});
35	  if (!urls.length && !entries.length) return '';
36	  let html = '<div style="margin-top:6px;padding-top:6px;border-top:1px dashed #eceef1;font-size:11px;">';
37	  html += '<div style="color:#1456f0;font-weight:600;margin-bottom:3px;">📦 前台变体监测</div>';
38	  for (const url of urls) {
39	    const fd = frontData && frontData[url];
40	    html += '<div style="margin:4px 0;padding:4px 6px;background:#f0f5ff;border-radius:4px;">';
41	    html += '<a href="' + esc(url) + '" target="_blank" style="font-size:10px;color:#1456f0;">' + esc((fd && fd.title) || url.split('/').pop() || '商品页') + '</a>';
42	    if (fd) {
43	      html += '<span style="color:#8a9099;margin-left:6px;">' + esc(fmtTs(fd.ts)) + '</span>';
44	      if (fd.price) html += ' <span style="color:#16a34a;font-weight:600;">' + esc(fd.price) + '</span>';
45	      html += '<br>';
46	      if (Array.isArray(fd.variants)) {
47	        for (const g of fd.variants) {
48	          const opts = (g.options || []).map((o) => {
49	            const icon = o.disabled ? '⚫' : (o.selected ? '✅' : '⬜');
50	            return icon + esc(o.name || '?');
51	          }).join(' ');
52	          html += '<span style="color:#1f2329;">' + esc(g.group || '选项') + '：</span>' + opts + '<br>';
53	        }
54	      }
55	      html += '<span style="color:#8a9099;">共 ' + fd.totalOptions + ' 变体，可用 ' + fd.availableOptions + '</span>';
56	    } else {
57	      html += '<span style="color:#d97706;"> 待采集</span>';
58	      html += ' <button class="frontChk" data-store="' + esc(storeName) + '" data-url="' + esc(url) + '" style="font-size:10px;padding:1px 6px;">检查</button>';
59	    }
60	    html += '</div>';
61	  }
62	  html += '</div>';
63	  return html;
64	}
65	
66	async function refresh() {
67	  const s = await send('getStatus');
68	  const cfg = (s && s.config) || {};
69	  const stores = (s && s.stores) || {};
70	
71	  document.getElementById('cfg').textContent =
72	    '飞书：' + (cfg.webhook ? (cfg.enabled ? '已启用' : '已停用') : '未配置')
73	    + '　后台：' + (s && s.bgVersion ? s.bgVersion : '旧版·需强制刷新');
