# Broader search across recent temu transcripts for SKU-related conversation
$targets = @(
  'C:\Users\Administrator\.claude\projects\E--project-temu\4a22d0f1-e8c6-4e19-9496-1154898df1ae.jsonl',
  'C:\Users\Administrator\.claude\projects\E--project-temu-temu-plugin\d8f9ed66-7890-410c-9802-86c6ae1cf3d9.jsonl',
  'C:\Users\Administrator\.claude\projects\E--project-temu-temu-plugin\76c3ffcd-42ca-4b62-a3b8-f7de97f00179.jsonl'
)
foreach ($p in $targets) {
  if (-not (Test-Path $p)) { Write-Host "MISSING $p"; continue }
  Write-Host "=== $p size=$((Get-Item $p).Length) ==="
  # Use findstr which is more reliable for large files
  findstr /i /c:"sku" /c:"规格" /c:"parent/list" /c:"具体" "$p" 2>$null | Select-Object -First 15
}

# Extract user messages and assistant final texts related to SKU from the 7/22 session
$path = 'C:\Users\Administrator\.claude\projects\E--project-temu\4a22d0f1-e8c6-4e19-9496-1154898df1ae.jsonl'
# Stream and extract type + short content for user/assistant
$i = 0
Get-Content $path -Encoding UTF8 | ForEach-Object {
  $i++
  try {
    $o = $_ | ConvertFrom-Json -ErrorAction Stop
  } catch { return }
  $type = $o.type
  if ($type -notin @('user','assistant')) { return }
  $text = ''
  $c = $o.message.content
  if ($c -is [string]) { $text = $c }
  elseif ($c) {
    foreach ($part in $c) {
      if ($part.type -eq 'text' -and $part.text) { $text += $part.text + "`n" }
      elseif ($part.type -eq 'tool_use' -and $part.name) { $text += "[tool:$($part.name)] " }
    }
  }
  if ($text -match 'sku|SKU|规格|parent/list|变体|前台|skuSpec|suggestedPrice|具体') {
    $snippet = ($text -replace '\s+', ' ').Substring(0, [Math]::Min(350, ($text -replace '\s+', ' ').Length))
    Write-Host "L$i [$type] $snippet"
    Write-Host '---'
  }
}

# Also check plugin project transcripts
foreach ($path in @(
  'C:\Users\Administrator\.claude\projects\E--project-temu-temu-plugin\d8f9ed66-7890-410c-9802-86c6ae1cf3d9.jsonl',
  'C:\Users\Administrator\.claude\projects\E--project-temu-temu-plugin\76c3ffcd-42ca-4b62-a3b8-f7de97f00179.jsonl'
)) {
  Write-Host "##### $path #####"
  $i = 0
  Get-Content $path -Encoding UTF8 -ErrorAction SilentlyContinue | ForEach-Object {
    $i++
    try { $o = $_ | ConvertFrom-Json -ErrorAction Stop } catch { return }
    if ($o.type -notin @('user','assistant')) { return }
    $text = ''
    $c = $o.message.content
    if ($c -is [string]) { $text = $c }
    elseif ($c) {
      foreach ($part in $c) {
        if ($part.type -eq 'text' -and $part.text) { $text += $part.text }
      }
    }
    if ($text -match 'sku|SKU|规格|具体|变体|parent') {
      $clean = ($text -replace '\s+', ' ')
      $snippet = $clean.Substring(0, [Math]::Min(400, $clean.Length))
      Write-Host "L$i [$($o.type)] $snippet"
      Write-Host '---'
    }
  }
}

# Search index and all hit urls for sku-related endpoints
$idx = Get-Content 'E:\project\temu\temu-monitor\capture\_index.json' -Raw -Encoding UTF8 | ConvertFrom-Json
$idx | ForEach-Object {
  $u = $_.url
  if ($u -match 'sku|spec|parent|suggested|price|product') {
    [PSCustomObject]@{ hit=$_.hit; url=($u -replace 'https?://[^/]+',''); method=$_.method; status=$_.status; size=$_.size }
  }
} | Format-Table -AutoSize
Write-Host '--- sample urls containing sku ---'
$idx | Where-Object { $_.url -match 'sku' } | Select-Object -First 20 | ForEach-Object { $_.url }

