1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	importScripts('logger.js');
6	var log = TemuLogger.createLogger('bg');
7	
8	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
9	const DEFAULT_CONFIG = {
10	  webhook: '',
11	  intervalMinutes: 15,
12	  enabled: true,
13	  storeName: '',
14	  // 定时必提醒：每天固定时刻强制发飞书状态汇报（无异常也发，证明插件活着）
15	  mustRemindEnabled: true,
16	  mustRemindTimes: ['09:30', '16:30'],
17	  // 前台变体监测
18	  frontCheckEnabled: true,
19	  frontCheckIntervalHours: 3,
20	};
21	const MUST_REMIND_PREFIX = 'mustRemind|';
22	
23	// ---------------- 解析 ----------------
24	function parseCountStatus(body) {
25	  try {
26	    const j = JSON.parse(body);
27	    const list = j && j.result && j.result.skcTopStatusCountList;
28	    if (!Array.isArray(list)) return null;
29	    const pick = (s) => {
30	      const x = list.find((e) => e && e.skcTopStatus === s);
31	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
32	    };
33	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
34	  } catch (e) { log.warn('parseCountStatus: failed to parse response'); return null; }
35	}
36	function parsePageQuery(body) {
37	  try {
38	    const j = JSON.parse(body);
39	    const r = j && j.result;
40	    if (!r) return null;
41	    return { total: r.total };
42	  } catch (e) { log.warn('parsePageQuery: failed to parse response'); return null; }
43	}
44	function parseSkuSpecList(body) {
45	  try {
46	    const j = JSON.parse(body);
47	    // 尝试多种可能的数据路径（API 格式可能漂移）
48	    let list = j && j.result && j.result.list;
49	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecList;
50	    if (!Array.isArray(list)) list = j && j.result && j.result.skuSpecs;
51	    if (!Array.isArray(list)) list = j && j.result && j.result.data;
52	    if (!Array.isArray(list)) list = j && j.result && Array.isArray(j.result) ? j.result : null;
53	    if (!Array.isArray(list)) list = j && j.data && j.data.list;
54	    if (!Array.isArray(list)) list = j && Array.isArray(j.data) ? j.data : null;
55	    if (!Array.isArray(list)) {
56	      // 仍然找不到数组 → 保存原始响应便于排查并告警
57	      log.warn('parseSkuSpecList: result.list is not an array, result keys=' +
58	        (j && j.result ? Object.keys(j.result).slice(0, 12).join(',') : 'null'));
59	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
60	      return null;
61	    }
62	    const specs = list.map((it) => {
63	      if (!it || typeof it !== 'object') return null;
64	      return {
65	        skuId: it.skuId || it.skuIdStr || it.id || it.skuSpecId || it.parentSkuId || '',
66	        name: it.specName || it.skuName || it.name || it.propValue || it.specValue || it.value || it.spec || '',
67	        img: it.skuImgUrl || it.imageUrl || it.imgUrl || it.thumbUrl || '',
68	      };
69	    }).filter((s) => s && (s.skuId || s.name));
70	    if (!specs.length) {
71	      log.warn('parseSkuSpecList: parsed ' + list.length + ' items but none had skuId/name, first item keys=' +
72	        (list[0] && typeof list[0] === 'object' ? Object.keys(list[0]).slice(0, 12).join(',') : typeof list[0]));
73	      chrome.storage.local.set({ lastSkuSpecRawFail: body.slice(0, 3000) });
74	      return null;
75	    }
76	    return { skuSpecs: specs, skuSpecCount: specs.length };
77	  } catch (e) { log.warn('parseSkuSpecList: failed to parse response: ' + (e && e.message ? e.message : String(e))); return null; }
78	}
79	function parseSkuPriceQuery(body) {
80	  try {
81	    const j = JSON.parse(body);
82	    const r = j && j.result;
83	    if (!r) return null;
84	    // 数据结构未知，先整体保存，后续按需解析
85	    return { skuPriceRaw: r };
86	  } catch (e) { log.warn('parseSkuPriceQuery: failed to parse response'); return null; }
87	}
88	
89	// ---------------- 存取 ----------------
90	async function getConfig() {
91	  const { config } = await chrome.storage.local.get('config');
92	  return Object.assign({}, DEFAULT_CONFIG, config || {});
93	}
94	async function getStores() {
95	  const { stores } = await chrome.storage.local.get('stores');
96	  return stores || {};
97	}
98	async function saveStores(stores) {
99	  await chrome.storage.local.set({ stores });
100	}

