135	function parseHHMM(s) {
136	  const m = String(s || '').trim().match(/^(\d{1,2})[:.：](\d{2})$/);
137	  if (!m) return null;
138	  const h = Number(m[1]);
139	  const min = Number(m[2]);
140	  if (h > 23 || min > 59) return null;
141	  return { h, min, label: String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0') };
142	}
143	// 下一次触发时间戳（本地时区）；若今天该时刻已过（或 5 秒内），排到明天
144	function nextWhen(hhmm) {
145	  const p = parseHHMM(hhmm);
146	  if (!p) return null;
147	  const now = new Date();
148	  const t = new Date(now.getFullYear(), now.getMonth(), now.getDate(), p.h, p.min, 0, 0);
149	  if (t.getTime() <= now.getTime() + 5000) t.setDate(t.getDate() + 1);
150	  return t.getTime();
151	}
152	function fmtNum(v) { return typeof v === 'number' ? String(v) : '—'; }
