154	  const cfg = await getConfig();
155	  if (!cfg.enabled || cfg.mustRemindEnabled === false) {
156	    log.info('MustRemind skipped: disabled');
157	    return { ok: false, msg: '未启用' };
158	  }
159	  if (!cfg.webhook) {
160	    log.warn('MustRemind skipped: no webhook');
