162	  }
163	  const stores = await getStores();
164	  const names = Object.keys(stores).sort();
165	  const lines = [
166	    '**定时必提醒' + (slot ? ' · ' + slot : '') + '**',
167	    '_插件存活汇报（无异常也会发）_',
168	    '',
169	  ];
170	  if (!names.length) {
171	    lines.push('_暂无店铺数据。请打开 goods/list 或点「轮巡所有店」。_');
172	  } else {
173	    for (const name of names) {
174	      const L = (stores[name] && stores[name].latest) || {};
175	      const stale = L.ts && (Date.now() - L.ts > 2 * 60 * 60 * 1000);
176	      lines.push('**🏬 ' + name + '**' + (stale ? ' ⚠️数据超过2小时未更新' : ''));
177	      lines.push(
178	        '在售 **' + fmtNum(L.onSale) + '**'
179	        + ' · 待关注 **' + fmtNum(L.trafficWatch) + '**'
180	        + ' · 下降 **' + fmtNum(L.trafficDecline) + '**'
181	        + ' · 总数 ' + fmtNum(L.total)
182	      );
183	      lines.push('上次检查：' + (L.ts ? new Date(L.ts).toLocaleString('zh-CN') : '—'));
184	      lines.push('');
185	    }
186	  }
187	  const lastCycle = (await chrome.storage.local.get('lastCycle')).lastCycle;
188	  if (lastCycle && lastCycle.ts) {
189	    lines.push('上次轮巡：' + new Date(lastCycle.ts).toLocaleString('zh-CN'));
190	  }
191	  lines.push('_汇报时间：' + new Date().toLocaleString('zh-CN') + '_');
192	  const r = await sendFeishu(cfg.webhook, '📋 Temu 监测定时汇报', lines, 'blue');
193	  await chrome.storage.local.set({ lastMustRemind: { ts: Date.now(), ok: r.ok, msg: r.msg, slot: slot || '' } });
194	  log.info('MustRemind done: slot=' + (slot || '') + ' ok=' + r.ok);
195	  return r;
196	}
197	async function setupMustRemindAlarms() {
198	  const all = await chrome.alarms.getAll();
199	  for (const a of all) {
200	    if (a.name.startsWith(MUST_REMIND_PREFIX)) await chrome.alarms.clear(a.name);
201	  }
202	  const cfg = await getConfig();
203	  if (cfg.mustRemindEnabled === false) {
204	    log.info('MustRemind alarms cleared (disabled)');
205	    return;
206	  }
207	  const raw = Array.isArray(cfg.mustRemindTimes) && cfg.mustRemindTimes.length
208	    ? cfg.mustRemindTimes
209	    : DEFAULT_CONFIG.mustRemindTimes;
210	  const seen = {};
211	  for (const t of raw) {
212	    const p = parseHHMM(t);
