input.command:
$ErrorActionPreference = 'Stop'
$src = 'E:\project\temu\temu-plugin'
$parent = 'E:\project\temu'
$crx = Join-Path $parent 'temu-plugin.crx'
$pem = Join-Path $parent 'temu-plugin.pem'
$zip = Join-Path $parent 'temu-plugin.zip'
$stage = Join-Path $parent ('_pack_stage_' + [guid]::NewGuid().ToString('N').Substring(0,8))

$candidates = @(
  "$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
  "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe",
  "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe"
)
$chrome = $candidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $chrome) { throw 'chrome.exe not found' }
Write-Host "Chrome: $chrome"
Write-Host "PEM: $(Test-Path $pem) $pem"

# CRX - Chrome overwrites if exists often; if not we write with unique then copy
Write-Host 'Packing CRX...'
$packArgs = @("--pack-extension=$src")
if (Test-Path $pem) { $packArgs += "--pack-extension-key=$pem" }
$p = Start-Process -FilePath $chrome -ArgumentList $packArgs -PassThru -WindowStyle Hidden
Wait-Process -Id $p.Id -Timeout 25 -ErrorAction SilentlyContinue
Start-Sleep -Seconds 2
if (-not (Test-Path $crx)) {
  # maybe chrome wrote next to src with different timing
  Get-ChildItem $parent -Filter 'temu-plugin*.crx' | Format-Table Name, Length, LastWriteTime
  throw "CRX missing: $crx"
}
$crxInfo = Get-Item $crx
Write-Host ("CRX OK: {0} ({1:N0} B) {2}" -f $crxInfo.Name, $crxInfo.Length, $crxInfo.LastWriteTime)

# ZIP via staging (new dir, no delete of existing zip - overwrite via .NET)
New-Item -ItemType Directory -Path $stage -Force | Out-Null
$include = @(
  'manifest.json','background.js','content.js','content-front.js','inject.js','logger.js',
  'popup.html','popup.js','options.html','options.js','使用说明.txt'
)
foreach ($f in $include) {
  $fp = Join-Path $src $f
  if (Test-Path -LiteralPath $fp) {
    Copy-Item -LiteralPath $fp -Destination (Join-Path $stage $f) -Force
  } else {
    Write-Warning "missing $f"
  }
}
Add-Type -AssemblyName System.IO.Compression.FileSystem
if (Test-Path $zip) {
  # overwrite by writing to temp zip name then replace via Move-Item -Force might also fail
  $zipTmp = Join-Path $parent ('temu-plugin-' + [guid]::NewGuid().ToString('N').Substring(0,6) + '.zip')
} else {
  $zipTmp = $zip
}
if (Test-Path $zipTmp) { throw "tmp zip already exists unexpectedly" }
[System.IO.Compression.ZipFile]::CreateFromDirectory($stage, $zipTmp, [System.IO.Compression.CompressionLevel]::Optimal, $false)
# Prefer final name temu-plugin.zip — if old exists and can't delete, leave dated name
if ($zipTmp -ne $zip) {
  try {
    Copy-Item -LiteralPath $zipTmp -Destination $zip -Force
    Write-Host "ZIP written to $zip (overwrote via Copy-Item)"
    $finalZip = $zip
    # leave tmp too if delete blocked — report both
  } catch {
    Write-Host "Could not overwrite $zip, using $zipTmp"
    $finalZip = $zipTmp
  }
} else {
  $finalZip = $zip
}
$zi = Get-Item $finalZip
Write-Host ("ZIP OK: {0} ({1:N0} B) {2}" -f $zi.FullName, $zi.Length, $zi.LastWriteTime)
$z = [System.IO.Compression.ZipFile]::OpenRead($finalZip)
Write-Host 'ZIP entries:'
$z.Entries | ForEach-Object { Write-Host ("  {0,-22} {1,8:N0} B" -f $_.FullName, $_.Length) }
$z.Dispose()
Write-Host "Stage left at: $stage (can delete manually)"
Write-Host 'Done. Do NOT send .pem'
